// Writes components/book/CATALOG.md from components/book/catalog.ts: every book component,
// what it's for, its props and an example, in one file a writing agent can read.
// `node scripts/catalog.mjs --check` fails instead if the file is out of date.
import { readFileSync, writeFileSync } from 'node:fs';
import { catalog, groups } from '../components/book/catalog.ts';

const out = new URL('../components/book/CATALOG.md', import.meta.url);

const lines = [
  '# Book components',
  '',
  '<!-- Generated by `just catalog` from components/book/catalog.ts. Edit that file, not this one. -->',
  '',
  'Everything a chapter\'s MDX can use, without imports. Live demos: `/components` on the dev site (`just run`).',
  '',
  '- Diagrams show **facts from the spec or precomputed data**, never the code a section asks the reader to write.',
  '- Every diagram takes an optional `caption`; cite its source there when it reproduces a spec or datasheet.',
  '- `highlight` marks the one thing the text is talking about. Use it sparingly.',
  '- Math is plain MDX: `$inline$` and `$$ display $$`, typeset by KaTeX.',
  '',
];

for (const group of groups) {
  lines.push(`## ${group}`, '');
  for (const c of catalog.filter((entry) => entry.group === group)) {
    lines.push(`### ${c.name}`, '', c.purpose, '', ...c.props.map((p) => `- ${p}`), '', '```mdx', c.usage, '```', '');
  }
}

const text = lines.join('\n');
if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {}
  if (current !== text) {
    console.error('components/book/CATALOG.md is out of date: run `just catalog`.');
    process.exit(1);
  }
} else {
  writeFileSync(out, text);
  console.log(`wrote components/book/CATALOG.md (${catalog.length} components)`);
}
